import{c as i,Q as a,j as n,m as t}from"./chunks/framework.BXc4yaFE.js";const m=JSON.parse('{"title":"DeepSeek-R1: Incentivizing Reasoning Capability in LLMs via Reinforcement Learning","description":"","frontmatter":{"url":"https://arxiv.org/abs/2501.12948","title":"DeepSeek-R1: Incentivizing Reasoning Capability in LLMs via Reinforcement Learning","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2501.12948,"authors":["DeepSeek-AI — Daya Guo","Dejian Yang","Haowei Zhang","et al. (200 co-authors)"],"pdf_path":"pdfs/2501.12948.pdf","published_date":"2025-01-22T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2025-01-22-deepseek-r1-reasoning-reinforcement-learning-2501-12948.md","filePath":"research/papers/2025-01-22-deepseek-r1-reasoning-reinforcement-learning-2501-12948.md","lastUpdated":1785909234000}'),r={name:"research/papers/2025-01-22-deepseek-r1-reasoning-reinforcement-learning-2501-12948.md"};function o(s,e,l,c,d,g){return a(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="deepseek-r1-incentivizing-reasoning-capability-in-llms-via-reinforcement-learning" tabindex="-1">DeepSeek-R1: Incentivizing Reasoning Capability in LLMs via Reinforcement Learning <a class="header-anchor" href="#deepseek-r1-incentivizing-reasoning-capability-in-llms-via-reinforcement-learning" aria-label="Permalink to &quot;DeepSeek-R1: Incentivizing Reasoning Capability in LLMs via Reinforcement Learning&quot;">​</a></h1><p><strong>Authors:</strong> DeepSeek-AI — Daya Guo, Dejian Yang, Haowei Zhang, et al. (200 co-authors) <strong>Year:</strong> 2025 <strong>Submitted:</strong> January 22, 2025 <strong>Venue:</strong> Nature, Vol. 645, pp. 633–638 (2025) <strong>ArXiv:</strong> <a href="https://arxiv.org/abs/2501.12948" target="_blank" rel="noreferrer">https://arxiv.org/abs/2501.12948</a></p><hr><h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>We present DeepSeek-R1, a large language model trained to reason through reinforcement learning (RL), without relying on human-annotated chain-of-thought (CoT) supervision. Our approach incentivizes the model to develop reasoning capabilities emergently, through exposure to verifiable tasks with outcome-based reward signals. Starting from a pre-trained base model, RL training enables the spontaneous emergence of sophisticated reasoning behaviors — including self-reflection, solution verification, hypothesis backtracking, and adaptive strategy selection — which were not explicitly programmed or demonstrated.</p><p>DeepSeek-R1 achieves performance matching or exceeding OpenAI o1 on a suite of challenging benchmarks including AIME 2024 (competition mathematics), Codeforces (competitive programming), and a range of STEM reasoning evaluations. We further demonstrate that the extended chain-of-thought reasoning patterns learned by DeepSeek-R1 can be distilled into significantly smaller models, enabling efficient deployment of o1-class reasoning without full-scale RL training. We open-source the model weights and describe our training methodology in full, enabling community replication of o1-class reasoning capabilities.</p><hr><h2 id="key-contributions" tabindex="-1">Key Contributions <a class="header-anchor" href="#key-contributions" aria-label="Permalink to &quot;Key Contributions&quot;">​</a></h2><ul><li><strong>Pure RL reasoning emergence</strong>: Demonstrates that advanced multi-step reasoning — including self-reflection, backtracking, and verification — can emerge from RL training alone, without human-annotated CoT demonstrations.</li><li><strong>Outcome-based reward signal</strong>: Uses verifiable task outcomes (mathematical correctness, code execution pass/fail) as reward signals, eliminating the need for expensive human step-level labeling.</li><li><strong>Benchmark parity with OpenAI o1</strong>: Achieves performance matching or exceeding o1 on AIME 2024 (competition math), Codeforces (competitive coding), and STEM reasoning benchmarks.</li><li><strong>Knowledge distillation of reasoning</strong>: Shows that long chain-of-thought reasoning patterns from DeepSeek-R1 can be distilled into smaller models (1.5B–70B parameters), yielding efficient o1-class reasoning at reduced cost.</li><li><strong>Full open-source release</strong>: Publishes model weights and training methodology, enabling broad community replication — the first fully open reproduction of o1-class reasoning capability.</li><li><strong>Nature publication</strong>: Results published in Nature (Vol. 645, 2025), reflecting independent peer review of the core empirical claims.</li></ul><hr><h2 id="methodology" tabindex="-1">Methodology <a class="header-anchor" href="#methodology" aria-label="Permalink to &quot;Methodology&quot;">​</a></h2><p>DeepSeek-R1 is trained via <strong>Group Relative Policy Optimization (GRPO)</strong>, a variant of Proximal Policy Optimization (PPO) adapted for language model training. The training process starts from a pre-trained base model (DeepSeek-V3-Base) and applies RL with verifiable reward signals: for mathematics problems, correctness of the final numerical answer; for code, passing of test cases. No intermediate step-level human labels are used. The model is incentivized purely to produce sequences that lead to correct final outputs.</p><p>A critical intermediate stage, <strong>DeepSeek-R1-Zero</strong>, is trained with pure RL from the base model without any supervised fine-tuning warm-up. Analysis of R1-Zero reveals spontaneous emergence of self-verification, reflection, and backtracking behaviors — the model learns to reconsider incorrect intermediate steps and try alternative approaches. This finding demonstrates that reasoning capabilities are latent in the pre-trained base model and can be elicited through RL incentives alone.</p><p>The final <strong>DeepSeek-R1</strong> model introduces a cold-start phase with a small amount of curated long-CoT SFT data before RL, which stabilizes early training and improves final performance and readability of reasoning traces. The resulting model generates extended &quot;thinking&quot; sequences — similar in structure to o1&#39;s extended reasoning — before producing a final answer. <strong>Knowledge distillation</strong> is performed by using DeepSeek-R1&#39;s reasoning traces as synthetic SFT data for training smaller models (Qwen and Llama base models at 1.5B, 7B, 8B, 14B, 32B, 70B scales), achieving strong performance without RL training at smaller scales.</p><hr><h2 id="main-results" tabindex="-1">Main Results <a class="header-anchor" href="#main-results" aria-label="Permalink to &quot;Main Results&quot;">​</a></h2><ul><li><strong>AIME 2024</strong>: DeepSeek-R1 achieves 79.8% pass@1, comparable to OpenAI o1 (79.2%).</li><li><strong>Codeforces</strong>: Reaches the 96.3rd percentile among human competitors, matching o1 performance.</li><li><strong>MATH-500</strong>: Achieves 97.3% accuracy, exceeding o1 (96.4%).</li><li><strong>MMLU</strong>: 90.8% accuracy, competitive with top frontier models.</li><li><strong>Distilled models</strong>: DeepSeek-R1-Distill-Qwen-32B achieves 72.6% on AIME 2024, surpassing o1-mini; the 7B distilled model outperforms QwQ-32B-Preview.</li><li><strong>DeepSeek-R1-Zero</strong> (pure RL, no SFT): achieves 71.0% on AIME 2024, demonstrating that extended reasoning emerges from RL alone.</li></ul><hr><h2 id="limitations-future-work" tabindex="-1">Limitations &amp; Future Work <a class="header-anchor" href="#limitations-future-work" aria-label="Permalink to &quot;Limitations &amp; Future Work&quot;">​</a></h2><ul><li>Language mixing: early RL training sometimes produces mixed-language outputs; the cold-start SFT phase mitigates but does not fully eliminate this.</li><li>Function calling and multi-turn conversation capabilities are weaker than specialized instruction-tuned models; reasoning-focused training trades off against instruction-following breadth.</li><li>Software engineering benchmarks (SWE-bench) show weaker relative performance compared to math/code competition tasks.</li><li>The RL training process is computationally expensive; training recipes for reproducing R1-scale RL at lower cost remain an open problem.</li><li>Future directions include extending verifiable reward signals to domains beyond math and code (e.g., science, law), and improving multi-modal reasoning.</li></ul><hr><h2 id="why-this-matters-for-ai-practitioners" tabindex="-1">Why This Matters for AI Practitioners <a class="header-anchor" href="#why-this-matters-for-ai-practitioners" aria-label="Permalink to &quot;Why This Matters for AI Practitioners&quot;">​</a></h2><p>DeepSeek-R1 is the most significant open-source development in inference-time reasoning to date. Its core finding — that o1-class reasoning emerges from RL on verifiable tasks without human CoT annotation — fundamentally changes the economics of training reasoning models. For practitioners, the open model weights enable direct deployment and fine-tuning of o1-class reasoning without API dependency. The distillation results are particularly actionable: a 7B or 32B model trained on R1&#39;s reasoning traces achieves performance that would have required a 70B+ model under standard SFT. The paper also validates the test-time compute scaling paradigm: R1&#39;s extended chain-of-thought generation is itself a form of inference-time compute allocation, confirming that longer reasoning traces correlate with higher accuracy on hard problems.</p>',23)])])}const p=i(r,[["render",o]]);export{m as __pageData,p as default};
